oxy_webhelp_navlinks = {"k8s_cluster_onboard_discover_rsc-d39307e26741":{"topics":[{"title":"Default protection sets","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> includes default protection sets that are automatically created         for Kubernetes clusters. These protection sets include all namespaces, and relieve you of         having to create protection sets manually.<\/p>","href":"kubernetes\/k8s_default_protection_sets.html","attributes":{"data-id":"k8s_default_protection_sets"},"menu":{"hasChildren":false},"tocID":"k8s_default_protection_sets-d39307e26758","topics":[]},{"title":"Adding a Kubernetes cluster to <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">To protect the applications and data in your Kubernetes cluster, add it to <span class=\"ph\">RSC<\/span> by uploading a kubeconfig, applying a generated manifest, or installing         with Helm.<\/p>","href":"kubernetes\/k8s_adding_k8s_cluster.html","attributes":{"data-id":"k8s_adding_k8s_cluster"},"menu":{"hasChildren":false},"tocID":"k8s_adding_k8s_cluster-d39307e26771","topics":[]},{"title":"Adding an Amazon EKS cluster to <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">To protect the applications and data in an Amazon EKS cluster, add the EKS cluster to             <span class=\"ph\">RSC<\/span> by configuring an AWS cloud account and an ARN for the EKS         cluster.<\/p>","href":"kubernetes\/k8s_adding_amazon_eks_cluster.html","attributes":{"data-id":"k8s_adding_amazon_eks_cluster"},"menu":{"hasChildren":false},"tocID":"k8s_adding_amazon_eks_cluster-d39307e26787","topics":[]},{"title":"Editing the Kubernetes cluster","shortdesc":"<p class=\"shortdesc\">Edit a Kubernetes cluster to update its configuration or refresh its connection to             <span class=\"ph\">RSC<\/span>.<\/p>","href":"kubernetes\/k8s_editing_kubernetes_cluster.html","attributes":{"data-id":"k8s_editing_kubernetes_cluster"},"menu":{"hasChildren":false},"tocID":"k8s_editing_kubernetes_cluster-d39307e26803","topics":[]},{"title":"Updating the dedicated backup network configuration","shortdesc":"<p class=\"shortdesc\">Turn on, change, or turn off the dedicated backup network to control how <span class=\"ph\">RSC<\/span>         routes backup traffic for an existing Kubernetes cluster.<\/p>","href":"kubernetes\/k8s_updating_backup_network_config.html","attributes":{"data-id":"k8s_updating_backup_network_config"},"menu":{"hasChildren":false},"tocID":"k8s_updating_backup_network_config-d39307e26817","topics":[]},{"title":"Affinity for Rubrik Backup Agent pod placement","shortdesc":"<p class=\"shortdesc\">You can use affinity to pin Rubrik Backup Agent pods to the availability zone of the         Persistent Volume you are backing up. This ensures that backup workloads run on nodes that         can access the volumes they need.<\/p>","href":"kubernetes\/k8s_rba_affinity.html","attributes":{"data-id":"k8s_rba_affinity"},"menu":{"hasChildren":false},"tocID":"k8s_rba_affinity-d39307e26831","next":"k8s_rba_affinity-d39307e26831"},{"title":"Manifest-based onboarding resources","shortdesc":"<p class=\"shortdesc\">When you onboard a Kubernetes cluster using the manifest-based method, <span class=\"ph\">RSC<\/span> deploys         some resources in the Kubernetes cluster. After the connection is established, <span class=\"ph\">RSC<\/span> deploys additional resources during the first refresh job.<\/p>","href":"kubernetes\/k8s_manifest_based_onboarding_resources.html","attributes":{"data-id":"k8s_manifest_based_onboarding_resources"},"menu":{"hasChildren":false},"tocID":"k8s_manifest_based_onboarding_resources-d39307e26864","topics":[]},{"title":"Deleting a Kubernetes cluster","shortdesc":"<p class=\"shortdesc\">Delete a Kubernetes cluster from <span class=\"ph\">RSC<\/span> to stop protecting the data and         applications associated with the protection sets of the cluster.<\/p>","href":"kubernetes\/k8s_deleting_k8s_cluster.html","attributes":{"data-id":"k8s_deleting_k8s_cluster"},"menu":{"hasChildren":false},"tocID":"k8s_deleting_k8s_cluster-d39307e26881","topics":[]},{"title":"Viewing the manifest file","shortdesc":"<p class=\"shortdesc\">For Kubernetes clusters that were added to <span class=\"ph\">RSC<\/span> using an manifest         file, you can view that file to determine whether it is producing the appropriate state for         Kubernetes objects within the cluster.<\/p>","href":"kubernetes\/k8s_viewing_manifest_file.html","attributes":{"data-id":"k8s_viewing_manifest_file"},"menu":{"hasChildren":false},"tocID":"k8s_viewing_manifest_file-d39307e26895","topics":[]},{"title":"Viewing Helm values","shortdesc":"<p class=\"shortdesc\">View the Helm values file for a Kubernetes cluster to verify the deployed         configuration or regenerate the file before running <code class=\"ph codeph\">helm         upgrade<\/code>.<\/p>","href":"kubernetes\/k8s_viewing_helm_values.html","attributes":{"data-id":"k8s_viewing_helm_values"},"menu":{"hasChildren":false},"tocID":"k8s_viewing_helm_values-d39307e26909","topics":[]},{"title":"Verifying the Helm chart signature","shortdesc":"<p class=\"shortdesc\">Verify the signature of the Kubernetes protection Helm chart using the Cosign CLI to         confirm the chart is authentic.<\/p>","href":"kubernetes\/k8s_verifying_helm_chart.html","attributes":{"data-id":"k8s_verifying_helm_chart"},"menu":{"hasChildren":false},"tocID":"k8s_verifying_helm_chart-d39307e26924","topics":[]},{"title":"Kubernetes protection image tags","shortdesc":"<p class=\"shortdesc\">Rubrik publishes the Kubernetes protection images to Docker Hub with version tags         that match the Rubrik         CDM         version.<\/p>","href":"kubernetes\/k8s_image_tags.html","attributes":{"data-id":"k8s_image_tags"},"menu":{"hasChildren":false},"tocID":"k8s_image_tags-d39307e26935","next":"k8s_image_tags-d39307e26935"},{"title":"Refreshing a Kubernetes cluster","shortdesc":"<p class=\"shortdesc\">Start a refresh of a Kubernetes cluster to update the information for the protected         namespaces on that cluster.<\/p>","href":"kubernetes\/k8s_refreshing_k8s_cluster.html","attributes":{"data-id":"k8s_refreshing_k8s_cluster"},"menu":{"hasChildren":false},"tocID":"k8s_refreshing_k8s_cluster-d39307e26957","topics":[]},{"title":"Regenerating the manifest file","shortdesc":"<p class=\"shortdesc\">Regenerate the manifest file to update the Kubernetes cluster         configuration.<\/p>","href":"kubernetes\/regenerating_manifest_file.html","attributes":{"data-id":"regenerating_manifest_file"},"menu":{"hasChildren":false},"tocID":"regenerating_manifest_file-d39307e26968","topics":[]},{"title":"Kubernetes diagnostics","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> Kubernetes diagnostics confirm connectivity and access         permissions for a Kubernetes cluster connected to a Rubrik cluster. You can use Kubernetes         diagnostics to verify and troubleshoot connectivity, backup, and recovery of a Kubernetes         object or component.<\/p>","href":"kubernetes\/kubernetes_diagnostics.html","attributes":{"data-id":"kubernetes_diagnostics"},"menu":{"hasChildren":false},"tocID":"kubernetes_diagnostics-d39307e26979","next":"kubernetes_diagnostics-d39307e26979"}]}};